sys_script_include.script:
var HoCOHSM_Retrieve_Info = Class.create();
HoCOHSM_Retrieve_Info.prototype = {
    initialize: function() {
    },
	getEmployeeNumber: function(user_sys_id){
		var gr = new GlideRecord('sys_user');
		gr.get('sys_id', user_sys_id);
		gr.query();

		var business_phone = "";
		var mobile_phone = "";

		while (gr.next()){
			business_phone = gr.getValue("phone");
			mobile_phone =  gr.getValue("mobile_phone");
		}

		if (business_phone != null){
			return business_phone;
		}
		else if (mobile_phone != null)
		{
			return mobile_phone;
		}
		else {
			return "N/A";
		}
	},
    type: 'HoCOHSM_Retrieve_Info'
};
